(() => {
  'use strict';
  const $ = (s) => document.querySelector(s);
  const params = new URLSearchParams(location.search);
  let view = ['home','director','workbench'].includes(params.get('view')) ? params.get('view') : 'home';
  let theme = params.get('theme') === 'dark' ? 'dark' : 'light';
  let step = 0, completed = -1, showReview = false, filmReady = false, mode = 'full', approved = [false,false], boardsReady = false, composed = false, pendingQuote = null;
  let projectName = '白露 · 精华上新短片', product = '白露保湿精华', brief = '为新品精华制作一支干净、克制的商品短片。突出白色磨砂瓶身与水润质感，保留产品原貌。', platform = '小红书 / 竖屏', tone = '自然 · 纯净 · 柔光';
  let kind = 'image', ratio = '1:1', size = '2K', purpose = '白底商品图', prompt = '白色磨砂精华瓶，柔和自然光，浅灰白背景。保留瓶身比例与标签，构图留白，呈现细腻质感。', polished = false, generated = false, filter = 'all';
  const shots = ['柔和自然光下，精华瓶完整入镜。镜头缓慢推近，建立纯净、安静的第一印象。','镜头靠近磨砂瓶身与水滴纹样，让侧光勾勒细节，保持商品形状和标签。'];
  const titles = ['确认创作需求','脚本与镜头','审核分镜画面','选择视频交付方式','收好这次创作'];
  const stages = ['需求','脚本与镜头','分镜审核','视频生成','交付'];
  const img = (n = 1) => `assets/scene-${n}.jpg`;
  const esc = (v) => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const arrow = '<span class="arrow" aria-hidden="true">↗</span>';
  const button = (text, action, cls = 'primary', extra = '') => `<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
  function toast(text) { $('#toast').textContent = text; $('#toast').hidden = false; clearTimeout(toast.timer); toast.timer = setTimeout(() => $('#toast').hidden = true, 3400); }
  function url() { const next = new URL(location.href); next.searchParams.set('view',view); next.searchParams.set('theme',theme); history.replaceState(null,'',next); }
  function go(next) { view = next; url(); render(); window.scrollTo({top:0,behavior:'instant'}); }
  function preview(content) { $('#preview-content').innerHTML = content; $('#preview').showModal(); }
  function closePreview() { $('#preview').querySelectorAll('video').forEach(v=>v.pause()); $('#preview').close(); }
  function stageSummary(i) { return [product + ' · 10 秒 · 9:16', '2 个镜头，分别为 5 秒', '2 版画面已逐镜审核', mode === 'full' ? '完整视频 · 顺序合成' : '分镜视频 · 2 个独立片段', '视频与项目过程可回看'][i]; }
  function goStep(i) { if (i > completed + 1) return; step = i; showReview = false; render(); window.scrollTo({top:0,behavior:'instant'}); }
  function invalidateFrom(i) { completed = Math.min(completed,i-1); pendingQuote = null; if (i < 4) { filmReady = false; composed = false; } if (i < 2) { approved = [false,false]; boardsReady = false; } }
  function home() {
    const cards = [{name:projectName,caption:'新品系列 / 商品短片',state:'需求待确认',image:1,stage:0},{name:'纯净质感 · 细节练习',caption:'画面研究 / 分镜视频',state:'分镜待审核',image:2,stage:2},{name:'白露 · 产品基础视觉',caption:'品牌素材 / 已完成示例',state:'查看完整项目',image:1,stage:4}];
    return `<div class="page"><div class="page-heading"><div><div class="eyebrow">YOUR CREATIVE SPACE</div><h1>每个好作品，<br>从一个清晰的想法开始。</h1><p class="subtle">把商品、想法与每一次选择，留在同一个项目里。</p></div><div class="date-note">A PLACE FOR YOUR NEXT IDEA<strong>01 — 03</strong>PROJECTS / 示例项目</div></div>
      <div class="home-launch"><section class="hero-create"><div class="hero-copy"><span class="mini-label">01 / START A PROJECT</span><h2>新建项目<br>一步步，做到成片。</h2><p>从商品需求出发，确认脚本、审核分镜，再生成你想要的版本。</p>${button('新建创作项目 '+arrow,'new-project')}</div><div class="hero-image"><img src="${img()}" alt="白色精华瓶商品示例"><div class="image-tag"><span>PRODUCT IN FOCUS</span><span>STUDIO 01</span></div></div></section>
      <section class="quick-launch"><div class="quick-top"><span class="quick-sign" aria-hidden="true">↗</span><span class="mini-label">02 / QUICK CREATE</span></div><h2>灵感来了，直接做。</h2><p>只需要一张商品图，或一段短视频？<br>在快捷工作台轻装开始。</p>${button('打开快捷工作台 '+arrow,'workbench','text-button')}</section></div>
      <div class="section-head"><h2>最近的项目 <small>RECENT PROJECTS</small></h2><div class="filter-buttons"><button data-filter="all" class="${filter==='all'?'active':''}">全部</button><button data-filter="working" class="${filter==='working'?'active':''}">进行中</button><button data-filter="done" class="${filter==='done'?'active':''}">已完成</button></div></div>
      <div class="project-grid">${cards.filter((_,i)=>filter==='all'||(filter==='working'?i<2:i===2)).map((card)=>`<button class="project-card" data-project-stage="${card.stage}" data-project-name="${esc(card.name)}"><div class="project-cover ${card.image===2?'wide':'tint'}"><img src="${img(card.image)}" alt="${esc(card.name)}项目封面"><span class="cover-name">BAILU<br>PRODUCT STUDY</span><span class="project-status">${card.state}</span></div><div class="project-info"><div><h3>${esc(card.name)}</h3><p>${card.caption}</p></div>${arrow}</div></button>`).join('')}</div><div class="bottom-note"><span>创作不必一次想清楚。你可以随时回来，继续上一版。</span><span>所有项目均为本地交互示例</span></div></div>`;
  }
  function nextButton(label, enabled = true) { return `<div class="step-action">${button(label+' <span aria-hidden="true">→</span>','next','primary',enabled?'':'disabled')}${step>0?button('← 返回上一步','back','text-button'):''}</div>`; }
  function assistant() {
    const kicker = `<div class="step-kicker">STEP 0${step+1} / 05</div><h2>${titles[step]}</h2>`;
    if (step===0) return `${kicker}<p class="intro">先告诉我，你希望观众看见什么。这里的选择会成为后续脚本与画面的共同依据。</p><label class="field">这次拍什么商品？<input id="product-input" value="${esc(product)}" maxlength="80"></label><label class="field">你希望突出什么？<textarea id="brief-input" rows="4">${esc(brief)}</textarea></label><label class="field">发布场景<select id="platform-input"><option ${platform.startsWith('小红书')?'selected':''}>小红书 / 竖屏</option><option ${platform.startsWith('抖音')?'selected':''}>抖音 / 竖屏</option><option ${platform.startsWith('商品')?'selected':''}>商品详情 / 横屏</option></select></label><div class="assistant-note"><strong>这次先做一支 10 秒短片</strong>用 2 个简洁镜头，把产品外观、细节和整体质感讲清楚。此处仅演示流程。</div>${nextButton('确认需求，继续')}`;
    if (step===1) return `${kicker}<p class="intro">先看整体节奏，再看每个镜头。你可以直接改右侧的画面描述，不需要一次接受整版建议。</p><div class="assistant-note"><strong>建议节奏：整体 → 细节</strong>开头让观众看清商品，第二镜突出质感，让画面保持简洁。</div><div class="info-row"><span>计划片长</span><strong>10 秒</strong></div><div class="info-row"><span>镜头数量</span><strong>2 个镜头 × 5 秒</strong></div><div class="info-row"><span>画面基调</span><strong>纯净 / 柔和 / 克制</strong></div><p class="subtle" style="font-size:10px;margin-top:18px">文字编辑只改变本页示例。确认后，下一步再审核实际画面。</p>${nextButton('确认脚本与镜头')}`;
    if (step===2 && !boardsReady) return `${kicker}<p class="intro">先核对本次分镜范围和费用，再生成画面。生成后，每张图都需要你单独审核。</p><div class="assistant-note"><strong>本次分镜范围</strong>镜头 01 / 完整商品<br>镜头 02 / 瓶身细节<br>每镜 1 张图，共 2 张。</div><div class="info-row"><span>图片模型</span><strong>Seedream 5.0 Flash</strong></div><div class="info-row"><span>规格</span><strong>2K · 9:16 · 参考图</strong></div><div class="step-action">${button('查看分镜示例报价','quote-boards','primary')}${button('← 返回脚本与镜头','back','text-button')}<p class="field-help">确认后展示预置图片，不调用模型、不产生费用。</p></div>`;
    if (step===2) return `${kicker}<p class="intro">生成视频前，先确认商品有没有走样。逐镜检查瓶身、细节与构图，喜欢这版再通过。</p><div class="assistant-note"><strong>建议检查这三件事</strong>商品形状是否一致<br>标签与细节是否正确<br>构图是否留出需要的空间</div><div class="info-row"><span>已通过画面</span><strong>${approved.filter(Boolean).length} / 2</strong></div><p class="subtle" style="font-size:10px;margin-top:18px">这些图片是预置示例，不代表已调用模型生成。本页可以逐镜通过或撤回。</p>${nextButton('确认画面，进入视频',boardsReady&&approved.every(Boolean))}`;
    if (step===3) return `${kicker}<p class="intro">一次成片，还是保留独立镜头？两种方式都使用刚确认的画面与镜头计划。</p><div class="mode-grid"><button class="mode-card ${mode==='full'?'selected':''}" data-mode="full" aria-pressed="${mode==='full'}"><span class="mode-icon" aria-hidden="true">▣</span><h3>完整视频</h3><p>镜头按序组成一支短片。</p></button><button class="mode-card ${mode==='clips'?'selected':''}" data-mode="clips" aria-pressed="${mode==='clips'}"><span class="mode-icon" aria-hidden="true">▥</span><h3>分镜视频</h3><p>每个镜头保留为独立片段。</p></button></div><div class="generation-info"><div class="info-row"><span>本次范围</span><strong>2 个已审核镜头</strong></div><div class="info-row"><span>计划时长</span><strong>10 秒</strong></div><div class="info-row"><span>模型</span><strong>Seedance Pro Fast · 示例</strong></div></div><div class="step-action">${filmReady?nextButton('确认结果，前往交付'):button('查看整组视频示例报价','generate-film','primary')}<p class="field-help">仅展示预置视频；不提交任务，不产生费用。</p>${!filmReady?button('← 返回分镜审核','back','text-button'):''}</div>`;
    return `${kicker}<p class="intro">这一版已经可以回看。交付前，再检查一次商品细节与整体节奏；需要调整，可以回到对应步骤。</p><div class="assistant-note"><strong>${mode==='full'?'完整视频':'分镜视频'} · 预置演示结果</strong>计划 10 秒与示例文件实际时长分别展示。预览文件不代表本项目真实生成。</div>${button('查看完整项目记录','review-all','secondary')}<div class="generation-info"><div class="info-row"><span>需求、脚本与画面</span><strong>已确认示例</strong></div><div class="info-row"><span>交付方式</span><strong>${mode==='full'?'完整成片':'独立镜头'}</strong></div></div><div class="step-action">${mode==='full'?'<a class="primary" href="assets/sample-film.mp4" download="物料间-完整成片示例.mp4">下载完整成片示例 ↓</a>':button('查看两个独立镜头 ↓','scroll-clips','primary')}${button('← 返回生成结果','back','text-button')}</div>`;
  }
  function output() {
    if(step===0) return `<div class="output-head">创作简报 <small>BRIEF / 01</small></div><div class="brief-board"><div class="product-image"><img src="${img()}" alt="白色磨砂精华瓶，项目参考商品"><span class="image-caption">REFERENCE / 商品参考</span></div><div class="brief-item"><small>创作对象</small><p id="brief-product">${esc(product)}</p><div class="tag-list"><span class="tag">商品短片</span><span class="tag">10 秒</span></div></div><div class="brief-item"><small>画面关键词</small><p>${esc(tone)}</p><div class="tag-list"><span class="tag" id="brief-platform">${esc(platform)}</span></div></div></div>`;
    if(step===1) return `<div class="output-head">一支短片，两个镜头 <small>STORY / 02</small></div><div class="shot-list">${shots.map((text,i)=>`<article class="shot-row"><img src="${img(i===1?2:1)}" alt="镜头${i+1}参考"><div><h3>0${i+1} · ${['完整呈现','质感细节','留白收束'][i]}<span>5 秒</span></h3><textarea data-shot="${i}" aria-label="镜头${i+1}画面描述">${esc(text)}</textarea></div></article>`).join('')}</div><p class="field-help" style="margin-top:16px">可直接编辑每个镜头描述。修改后需要重新确认当前版本。</p>`;
    if(step===2&&!boardsReady) return `<div class="output-head">待生成分镜 <small>STORYBOARD / 03</small></div><div class="board-wait"><span aria-hidden="true">▧</span><h3>先确认，再看画面。</h3><p>这一步还没有生成分镜。<br>查看左侧的范围与示例报价，确认后逐镜审核。</p></div>`;
    if(step===2) return `<div class="output-head">逐镜审核 <small>STORYBOARD / 03</small></div><div class="boards-grid">${shots.map((_,i)=>`<article class="board-card ${approved[i]?'approved':''}"><img src="${img(i===1?2:1)}" alt="镜头${i+1}分镜示例"><div><h3>0${i+1} · ${['整体商品','瓶身细节','结束画面'][i]}</h3><p>检查商品形态与${i===1?'细节准确性':'画面构图'}</p><button data-approve="${i}" aria-pressed="${approved[i]}">${approved[i]?'✓ 已通过 · 撤回':'确认这版画面'}</button></div></article>`).join('')}</div>`;
    const head=step===3?(mode==='full'?'完整视频预览':'独立片段预览'):'本次交付';
    const ready=filmReady||step===4;
    const clips=mode==='clips'&&ready;
    return `<div class="output-head">${head}<small>${step===3?'GENERATE / 04':'DELIVERY / 05'}</small></div>${clips?`<div class="clip-delivery" id="clip-delivery">${[1,2].map(n=>`<article class="clip-card"><video src="assets/clip-${n}.mp4" controls preload="metadata" aria-label="镜头${n}独立示例片段"></video><div><h3>镜头 0${n} · ${n===1?'完整商品':'瓶身细节'}</h3><p>计划 5 秒 / 文件约 5.04 秒</p><a class="text-button" href="assets/clip-${n}.mp4" download="物料间-镜头0${n}-示例.mp4">下载这一镜 ↓</a></div></article>`).join('')}</div><div class="compose-offer"><div><strong>需要把片段连成一支视频？</strong><p>保留独立镜头，另行确认按 01 → 02 拼接。</p></div>${button(composed?'已确认合成 · 查看示例':'确认后合成','compose-clips','secondary')}</div>${composed?'<div class="video-frame"><video src="assets/sample-film.mp4" controls preload="metadata" aria-label="独立镜头合成后的预置示例"></video></div><p class="field-help">预置合成示例；本次未执行真实合成。</p>':''}`:`<div class="video-frame">${ready?'<video src="assets/sample-film.mp4" controls preload="metadata" aria-label="完整成片示例"></video>':`<div class="video-placeholder"><img src="${img()}" alt="视频生成等待确认"><span class="video-badge">等待范围、规格与费用确认</span></div>`}</div><div class="deliver-meta"><span>完整成片 / 示例</span><span>实际时长：以播放器为准</span></div>`}<div class="generation-info"><div class="info-row"><span>计划镜头</span><strong>01 → 02 / 共 10 秒</strong></div><div class="info-row"><span>画面基调</span><strong>${esc(tone)}</strong></div><div class="info-row"><span>当前状态</span><strong>${ready?'预置示例可预览':'等待明确确认'}</strong></div></div>`;
  }
  function director() { return `<div class="workspace"><div class="workspace-head"><div><div class="crumb"><button data-view="home">项目首页</button><span>/</span><span>PROJECT 01</span></div><h1>${esc(projectName)}<small>导演台</small></h1></div><div class="work-actions"><span class="status-dot">本页示例编辑</span>${button(completed===4?'完整项目':'当前记录','review-all','secondary')}</div></div><div class="director-layout"><aside class="stage-rail" aria-label="项目创作步骤"><div class="rail-heading">PROJECT PROGRESS</div>${stages.slice(0,Math.max(step,completed)+1).map((label,i)=>`<button class="stage-button ${i===step?'active':''} ${i<=completed?'done':''}" data-step="${i}" ${i>completed+1?'disabled':''} ${i===step?'aria-current="step"':''}><span class="stage-number">${i<=completed?'✓':`0${i+1}`}</span><span class="stage-label">${label}<small>${i<=completed?'已确认':i===step?'正在进行':'等待上一步'}</small></span></button>`).join('')}<p class="rail-foot">每次只做一个决定。<br>确认以后，再往前一步。</p></aside><div class="director-main"><div class="current-step"><section class="assistant-pane">${assistant()}</section><section class="stage-output">${output()}</section></div>${completed>=0?`<div class="summary-strip">${stages.slice(0,completed+1).map((label,i)=>`<button class="summary-chip" data-step="${i}"><span>✓</span>${label}已确认 · 编辑</button>`).join('')}</div>`:''}${showReview?`<section class="review-all" id="project-review"><h3>${completed===4?'完整项目记录':'当前项目记录'}</h3>${stages.slice(0,Math.max(step,completed)+1).map((label,i)=>`<div class="review-line"><strong>0${i+1} ${label}</strong><span>${i<=completed||i===4&&step===4?stageSummary(i):'尚未确认，完成前一步后继续。'}</span><button data-step="${i}" ${i>completed+1?'disabled':''}>查看</button></div>`).join('')}</section>`:''}</div></div></div>`; }
  function workbench() { return `<div class="workspace"><div class="workspace-head"><div><div class="eyebrow">QUICK CREATION</div><h1 style="margin-top:12px">让一个想法，先有画面。</h1></div><div class="work-actions"><span class="status-dot">独立于项目流程</span></div></div><div class="bench-layout"><section class="bench-controls"><div class="segmented"><button data-kind="image" class="${kind==='image'?'active':''}">生图</button><button data-kind="video" class="${kind==='video'?'active':''}">生视频</button></div><label class="field">${kind==='image'?'图片用途':'视频方式'}<select id="purpose-input">${(kind==='image'?['白底商品图','氛围场景图','自定义']:['首帧图生视频','文生视频']).map(v=>`<option ${purpose===v?'selected':''}>${v}</option>`).join('')}</select></label><div class="upload-box"><img src="${img()}" alt="预置商品参考图"><div><strong>商品参考图</strong>已使用本地示例 · ${button('查看','preview-image','text-button','style="min-height:20px;padding:0;font-size:10px"')}</div></div><label class="field">描述你想要的画面<textarea id="prompt-input" rows="5">${esc(prompt)}</textarea></label>${button('✧ 帮我润色描述（可选）','polish','text-button polish')}${polished?`<div class="polish-result">${esc(prompt)} 增加柔和侧光，让主体轮廓与材质细节更清晰，背景简洁，无额外装饰。<br>${button('采用这段示例润色','apply-polish','')}</div>`:''}<label class="field">模型<select><option>${kind==='image'?'Seedream 5.0 Flash':'Seedance 1.0 Pro Fast'}</option></select></label><span class="field">画面比例</span><div class="option-row">${(kind==='image'?['1:1','3:4','9:16','16:9']:['1:1','9:16','16:9']).map(v=>`<button data-ratio="${v}" class="${ratio===v?'active':''}" aria-pressed="${ratio===v}">${v}</button>`).join('')}</div><span class="field">${kind==='image'?'图片尺寸':'视频时长'}</span><div class="option-row">${(kind==='image'?['1K','2K']:['5 秒','10 秒']).map(v=>`<button data-size="${v}" class="${size===v?'active':''}" aria-pressed="${size===v}">${v}</button>`).join('')}</div>${button('查看本次示例报价 <span>→</span>','quick-generate')}<p class="field-help" style="text-align:center;margin-top:13px">使用预置示例，不调用模型。</p></section><section class="bench-results"><div class="bench-top"><h2>创作结果</h2><span>${generated?'刚刚预览':'示例素材'} · ${kind==='image'?'2 张图片':'1 段视频'}</span></div>${kind==='image'?`<div class="result-grid">${[1,2].map((n)=>`<article class="result-card"><button class="result-image" data-preview-image="${n}" aria-label="预览${n===1?'完整商品':'细节'}图片"><img src="${img(n)}" alt="${n===1?'白色精华瓶完整商品图':'瓶身细节图'}"><span class="image-tag"><span>BAILU / PRODUCT STUDY</span><span>0${n}</span></span></button><div class="result-info"><h3>${n===1?'纯净白底 · 产品全貌':'柔光细节 · 材质表达'}</h3><p>${size} · ${ratio} 设置示例，图片为预置素材</p><div class="result-actions">${button('放大预览','preview-image','',`data-image="${n}"`)}${button('用这张做视频 ↗','image-to-video','')}</div></div></article>`).join('')}</div>`:`<div class="video-frame"><video src="assets/sample-film.mp4" controls preload="metadata" aria-label="商品视频示例"></video></div><div class="deliver-meta"><span>${size}为所选参数 · 文件时长以播放器为准</span><span>预置示例</span></div>`}<p class="results-foot">需要连贯的多镜头作品？${button('带着想法去导演台 ↗','director','text-button','style="min-height:30px;padding:0;font-size:10px"')}<br>快捷工作台专注单次创作；项目导演台保留需求、脚本和审核过程。</p></section></div></div>`; }
  function render() { document.documentElement.dataset.theme = theme; document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===view)); $('#app').innerHTML = view==='home'?home():view==='director'?director():workbench(); $('#theme-button').textContent=theme==='light'?'◐':'☼'; $('#theme-button').setAttribute('aria-pressed',String(theme==='dark')); }
  function newProject() { preview(`<div class="modal-copy"><div class="eyebrow">NEW PROJECT</div><h2 style="margin-top:16px">给这次创作起个名字。</h2><p>从需求开始，一步步确认到交付。这是本页临时示例，刷新后不会保存。</p><label class="field">项目名称<input id="new-project-name" placeholder="例如：白露精华 · 上新短片" value="白露精华 · 上新短片" maxlength="80"></label><div class="modal-actions">${button('创建并进入导演台 →','create-project')}${button('取消','close','secondary')}</div></div>`); setTimeout(()=>$('#new-project-name')?.focus(),0); }
  function quoteSignature(type) { return JSON.stringify(type==='quick'?{kind,ratio,size,prompt,purpose}:{projectName,product,brief,platform,shots,approved,boardsReady,mode}); }
  function showQuote(type) {
    const image=type==='boards'||(type==='quick'&&kind==='image');
    const count=type==='quick'?(image?2:1):2;
    const model=image?'Seedream 5.0 Flash':'Seedance 1.0 Pro Fast';
    const spec=type==='quick'?(image?`${size} · ${ratio}`:`720p · ${ratio} · ${size}`):(image?'2K · 9:16':'720p · 9:16 · 每镜 5 秒');
    const total=image?'0.24':type==='quick'&&size==='5 秒'?'0.88':'1.76';
    pendingQuote={type,signature:quoteSignature(type)};
    preview(`<div class="modal-copy"><div class="eyebrow">SAMPLE QUOTE / NO CHARGE</div><h2 style="margin-top:16px">确认这一次创作</h2><p>先核对范围、规格与费用，再决定是否继续。以下价格是固定交互示例，不是实时估价或官方价格。</p><div class="quote-details"><div class="info-row"><span>生成范围</span><strong>${type==='boards'?'镜头 01、02 / 分镜图片':type==='film'?`镜头 01、02 / ${mode==='full'?'完整视频':'独立分镜视频'}`:image?'商品图片':'单段视频'}</strong></div><div class="info-row"><span>模型</span><strong>${model}</strong></div><div class="info-row"><span>规格</span><strong>${spec}</strong></div><div class="info-row"><span>数量</span><strong>${count} ${image?'张':'个镜头'}</strong></div><div class="info-row"><span>估算费用（示例）</span><strong class="quote-price">¥${total}</strong></div></div><p class="field-help" style="margin-top:16px">估算不等于账单。本原型只显示预置素材，不发送任务、不产生费用。${!image?'计划时长与示例文件实际时长可能不同。':''}</p><div class="modal-actions">${button('确认示例报价并继续','confirm-quote')}${button('返回修改','close','secondary')}</div></div>`);
  }
  document.addEventListener('click', e=>{
    const target=e.target.closest('button,a'); if(!target)return;
    if(target.dataset.view){e.preventDefault();go(target.dataset.view);return;}
    if(target.id==='theme-button'){theme=theme==='light'?'dark':'light';url();render();return;}
    if(target.matches('.modal-close')){closePreview();return;}
    if(target.dataset.filter){filter=target.dataset.filter;render();return;}
    if(target.dataset.projectStage){step=Number(target.dataset.projectStage);completed=step===4?4:step-1;approved=step>=3?[true,true]:[false,false];boardsReady=step>=3;filmReady=step===4;composed=false;pendingQuote=null;projectName=target.dataset.projectName;showReview=step===4;go('director');return;}
    if(target.dataset.step!==undefined){goStep(Number(target.dataset.step));return;}
    if(target.dataset.approve!==undefined){if(!boardsReady)return;approved[Number(target.dataset.approve)]=!approved[Number(target.dataset.approve)];invalidateFrom(2);render();return;}
    if(target.dataset.mode){mode=target.dataset.mode;filmReady=false;invalidateFrom(3);render();return;}
    if(target.dataset.kind){kind=target.dataset.kind;if(kind==='video'&&ratio==='3:4')ratio='9:16';pendingQuote=null;size=kind==='image'?'2K':'5 秒';purpose=kind==='image'?'白底商品图':'首帧图生视频';generated=false;render();return;}
    if(target.dataset.ratio){if(kind==='video'&&target.dataset.ratio==='3:4')return;ratio=target.dataset.ratio;pendingQuote=null;render();return;}
    if(target.dataset.size){size=target.dataset.size;pendingQuote=null;render();return;}
    if(target.dataset.previewImage){preview(`<img class="preview-image" src="${img(target.dataset.previewImage)}" alt="商品图片示例大图">`);return;}
    switch(target.dataset.action){
      case 'home':go('home');break;
      case 'workbench':go('workbench');break;
      case 'director':go('director');break;
      case 'new-project':newProject();break;
      case 'create-project':{const name=$('#new-project-name').value.trim();if(!name){$('#new-project-name').focus();return;}projectName=name;step=0;completed=-1;showReview=false;approved=[false,false];boardsReady=false;filmReady=false;composed=false;pendingQuote=null;closePreview();go('director');break;}
      case 'close':closePreview();break;
      case 'next':if(step===0&&(!product.trim()||!brief.trim())){toast('先填写商品名称和创作需求。');return;}if(step===1&&shots.some(text=>!text.trim())){toast('请为每个镜头保留画面描述。');return;}if(step===2&&(!boardsReady||!approved.every(Boolean)))return;if(step===3&&!filmReady)return;completed=Math.max(completed,step);step=Math.min(4,step+1);if(step===4)completed=4;showReview=false;render();window.scrollTo({top:0,behavior:'instant'});break;
      case 'back':goStep(Math.max(0,step-1));break;
      case 'quote-boards':if(step===2)showQuote('boards');break;
      case 'generate-film':if(step===3&&boardsReady&&approved.every(Boolean))showQuote('film');break;
      case 'confirm-quote':{
        if(!pendingQuote)return;
        const quote=pendingQuote;
        if(quote.signature!==quoteSignature(quote.type)){closePreview();toast('设置已改变，请重新查看报价。');pendingQuote=null;break;}
        if(quote.type==='boards'){boardsReady=true;approved=[false,false];}
        if(quote.type==='film')filmReady=true;
        if(quote.type==='quick')generated=true;
        pendingQuote=null;closePreview();render();toast('已确认示例报价并展示预置结果，没有调用模型或扣费。');
        if(quote.type==='quick'&&innerWidth<581)document.querySelector('.bench-results').scrollIntoView({behavior:'smooth'});break;
      }
      case 'compose-clips':if(!filmReady||mode!=='clips')return;preview(`<div class="modal-copy"><div class="eyebrow">ASSEMBLY CONFIRMATION</div><h2 style="margin-top:16px">确认组合这两个片段</h2><p>按镜头 01 → 02 顺序组合，保留两个原片段。计划 10 秒，素材合计约 10.08 秒；不裁剪，不新增模型生成。</p><div class="assistant-note">本原型只展示预置合成文件，没有执行合成，也没有费用。</div><div class="modal-actions">${button('确认，查看合成示例','confirm-compose')}${button('保留独立片段','close','secondary')}</div></div>`);break;
      case 'confirm-compose':if(filmReady&&mode==='clips'){composed=true;closePreview();render();toast('独立片段保留，已展示另一个合成示例。');}break;
      case 'scroll-clips':$('#clip-delivery')?.scrollIntoView({behavior:'smooth'});break;
      case 'review-all':showReview=!showReview;render();setTimeout(()=>$('#project-review')?.scrollIntoView({behavior:'smooth',block:'start'}),0);break;
      case 'preview-video':preview('<video class="preview-video" src="assets/sample-film.mp4" controls autoplay aria-label="本地视频示例"></video>');break;
      case 'preview-image':preview(`<img class="preview-image" src="${img(Number(target.dataset.image)||1)}" alt="预置商品参考图">`);break;
      case 'polish':polished=!polished;render();break;
      case 'apply-polish':prompt+=' 增加柔和侧光，让主体轮廓与材质细节更清晰，背景简洁，无额外装饰。';polished=false;render();toast('已采用示例润色，没有开始生成。');break;
      case 'quick-generate':if(!prompt.trim()){toast('先描述你希望看到的画面。');return;}showQuote('quick');break;
      case 'image-to-video':kind='video';if(ratio==='3:4')ratio='9:16';size='5 秒';pendingQuote=null;purpose='首帧图生视频';render();toast('参考图已带入视频设置（示例）。');window.scrollTo({top:0,behavior:'smooth'});break;
    }
  });
  document.addEventListener('input',e=>{
    if(e.target.id==='product-input'){product=e.target.value;invalidateFrom(0);$('#brief-product').textContent=product;}
    if(e.target.id==='brief-input'){brief=e.target.value;invalidateFrom(0);}
    if(e.target.dataset.shot!==undefined){shots[Number(e.target.dataset.shot)]=e.target.value;invalidateFrom(1);}
    if(e.target.id==='prompt-input'){prompt=e.target.value;pendingQuote=null;}
  });
  document.addEventListener('change',e=>{if(e.target.id==='platform-input'){platform=e.target.value;invalidateFrom(0);$('#brief-platform').textContent=platform;}if(e.target.id==='purpose-input'){purpose=e.target.value;pendingQuote=null;}});
  $('#preview').addEventListener('click',e=>{if(e.target===$('#preview'))closePreview();});
  $('#preview').addEventListener('close',()=>$('#preview').querySelectorAll('video').forEach(v=>v.pause()));
  render();
})();
